import{et as e,mt as t,s as n,tt as r}from"./chunks/framework.CHi0mXvr.js";var i=JSON.parse(`{"title":"ストーリーポイント","description":"ストーリーポイントは、作業の規模、複雑さ、不確実性を相対的に見積もるための単位です。絶対的な時間と直接マッピングするものではなく、スプリント単位での合理的な作業量の把握とチームのスケジュール見積もりを目的とします。","frontmatter":{"title":"ストーリーポイント","description":"ストーリーポイントは、作業の規模、複雑さ、不確実性を相対的に見積もるための単位です。絶対的な時間と直接マッピングするものではなく、スプリント単位での合理的な作業量の把握とチームのスケジュール見積もりを目的とします。","head":[["meta",{"name":"keywords","content":"スクラムバン, Scrumban, スクラムバン紹介, スクラムバンの概念, スクラムバンとは, Scrumban紹介, Scrumban概念, スクラムとカンバンの違い, スクラム vs カンバン, アジャイル方法論, アジャイルフレームワーク, カンバン方法論, スクラム方法論, スクラムバンプロセス, スクラムバン運用ガイド, スクラムバンボード, WIP制限, ワークフロー管理, カンバンボードの使い方, スクラムバンのメリット, スクラムバンの特徴, スクラムバンの効果, スクラムバン活用事例, スクラムバン導入効果, スクラムバン Jira設定, スクラムバンボードテンプレート, Scrumbanツール, スクラムバンコラボレーションツール, スクラムバンワークフロー, アジャイルプロジェクト管理, 業務効率化方法論, 反復的作業管理, ボトルネック解消"}],["meta",{"property":"og:title","content":"スクラムバン"}],["meta",{"property":"og:description","content":"スクラムバン(Scrumban)は、スクラムの反復的構造とカンバンのフロー管理・WIP制限を組み合わせ、柔軟かつ効率的に作業を管理するハイブリッドアジャイル方法論です。"}],["meta",{"property":"og:image","content":"https://empasy.io/docs/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/agile/glossaryOfTerms.html"}],["link",{"rel":"canonical","href":"https://empasy.io/docs/ja/agile/storyPointGuide.html"}]],"sort":2000},"headers":[],"relativePath":"ja/agile/storyPointGuide.md","filePath":"ja/agile/storyPointGuide.md","lastUpdated":1786514511000}`),a={name:`ja/agile/storyPointGuide.md`};function o(n,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[r(`<h1 id="ストーリーポイントガイド-アジャイルチームのための作業見積もり方法" tabindex="-1">ストーリーポイントガイド：アジャイルチームのための作業見積もり方法 <a class="header-anchor" href="#ストーリーポイントガイド-アジャイルチームのための作業見積もり方法" aria-label="Permalink to “ストーリーポイントガイド：アジャイルチームのための作業見積もり方法”">​</a></h1><h2 id="ストーリーポイントとは" tabindex="-1">ストーリーポイントとは？ <a class="header-anchor" href="#ストーリーポイントとは" aria-label="Permalink to “ストーリーポイントとは？”">​</a></h2><p>ストーリーポイントは、作業の <strong>規模、複雑さ、不確実性</strong> を相対的に見積もる単位です。絶対的な時間と直接マッピングするものではなく、スプリント単位での合理的な作業量の把握とチームのスケジュール見積もりを目的とします。</p><blockquote><p>❌ 「5ポイント = 1ポイントの5倍の時間」というアプローチは間違っています</p></blockquote><h2 id="フィボナッチ数列を使用する理由" tabindex="-1">フィボナッチ数列を使用する理由 <a class="header-anchor" href="#フィボナッチ数列を使用する理由" aria-label="Permalink to “フィボナッチ数列を使用する理由”">​</a></h2><p>ストーリーポイントの見積もりには、一般的に <strong>1, 2, 3, 5, 8, 13, 21...</strong> のようなフィボナッチ数列を使用します。このように連続した数字ではない数列を使用する理由は以下の通りです。</p><ul><li>差が次第に大きくなり、不確実性を反映します</li><li>5と6の差よりも、5と8の差の方がより明確です</li><li>大きな作業になるほど、複雑さとリスクが指数関数的に増加することを反映します</li><li>結果として、チームの合意形成が容易になり、過大/過小見積もりを減らすことができます</li></ul><h2 id="ストーリーポイントの活用例" tabindex="-1">ストーリーポイントの活用例 <a class="header-anchor" href="#ストーリーポイントの活用例" aria-label="Permalink to “ストーリーポイントの活用例”">​</a></h2><table tabindex="0"><thead><tr><th>作業項目</th><th>ポイント</th><th>説明</th></tr></thead><tbody><tr><td>ユーザー調査</td><td>3ポイント</td><td>比較的軽い労力が必要な作業</td></tr><tr><td>ワイヤーフレーム</td><td>5ポイント</td><td>ユーザー調査後に進める簡単な作業</td></tr><tr><td>UIデザイン</td><td>8ポイント</td><td>チーム内での調整が必要な作業</td></tr><tr><td>開発作業</td><td>13ポイント</td><td>多くの要素が関与し、複雑な作業</td></tr><tr><td>QAテスト</td><td>8ポイント</td><td>複雑だが管理可能なレベルの作業</td></tr></tbody></table><h2 id="基準となる課題の例" tabindex="-1">基準となる課題の例 <a class="header-anchor" href="#基準となる課題の例" aria-label="Permalink to “基準となる課題の例”">​</a></h2><h3 id="ストーリーポイント-5-ユーザーパスワードリセット機能" tabindex="-1">ストーリーポイント 5：ユーザーパスワードリセット機能 <a class="header-anchor" href="#ストーリーポイント-5-ユーザーパスワードリセット機能" aria-label="Permalink to “ストーリーポイント 5：ユーザーパスワードリセット機能”">​</a></h3><p><strong>Doneの定義</strong></p><ul><li>パスワード変更機能の実装</li><li>メール認証機能の実装</li><li>パスワードルールの遵守 (英数字混合など)</li></ul><p><strong>補足の考慮事項</strong></p><ul><li>DBテーブルの設計</li><li>メールの送受信環境</li><li>例外事項は考慮しなくてもよい</li></ul><h3 id="ストーリーポイント-13-クレジットカード決済機能" tabindex="-1">ストーリーポイント 13：クレジットカード決済機能 <a class="header-anchor" href="#ストーリーポイント-13-クレジットカード決済機能" aria-label="Permalink to “ストーリーポイント 13：クレジットカード決済機能”">​</a></h3><p><strong>Doneの定義</strong></p><ul><li>商品決済機能の実装</li><li>マイページで購買履歴の照会が可能</li><li>管理者も確認可能</li></ul><p><strong>補足の考慮事項</strong></p><ul><li>カード登録機能は既に存在している</li><li>DB設計が必要</li><li>エラーパターンは考慮しなくてもよい</li></ul><h2 id="注意事項-間違った使い方" tabindex="-1">注意事項：間違った使い方 <a class="header-anchor" href="#注意事項-間違った使い方" aria-label="Permalink to “注意事項：間違った使い方”">​</a></h2><p><strong>時間をそのまま代入する方式は避けるべきです</strong></p><ul><li>❌ 「4時間の業務 = 1ポイント」 → 既存のやり方と変わらない</li><li>❌ 「5ポイント = 1ポイントの5倍の時間」</li></ul><p><strong>正しい意味</strong>：1ポイントよりも5倍複雑だという意味です。このような間違ったアプローチはストーリーポイントの本質を崩します。</p><h2 id="リファクタリングと品質の考慮事項" tabindex="-1">リファクタリングと品質の考慮事項 <a class="header-anchor" href="#リファクタリングと品質の考慮事項" aria-label="Permalink to “リファクタリングと品質の考慮事項”">​</a></h2><p>すべてのストーリーには、以下の2つの要素が必ず含まれていなければなりません。</p><ol><li><strong>正しく動作</strong>する機能</li><li><strong>適切に動作</strong>する品質</li></ol><p>1つ目の要素だけを満たし、2つ目の要素を無視すると、ストーリーポイントは不完全です。リファクタリング作業も、品質向上（技術的負債の解消）の観点からポイントを付与することができます。</p><blockquote><p>注意：ストーリーポイントは、個人の成果比較用には絶対に使用しないでください。これは純粋にチーム単位のツールです。</p></blockquote><h2 id="核心のまとめ" tabindex="-1">核心のまとめ <a class="header-anchor" href="#核心のまとめ" aria-label="Permalink to “核心のまとめ”">​</a></h2><ul><li>ストーリーポイントは <strong>相対的な見積もり単位</strong> です</li><li>時間換算ではなく、作業の <strong>複雑さ/不確実性の比較</strong> が目的です</li><li>フィボナッチ数列を使用し、大きな作業ほどリスクが大きくなるという点を反映します</li><li>チームの合意基準(3, 5, 8, 13など)を決めておき、新しい作業と比較して決定します</li><li>間違った時間対応の方式は避け、品質基準を必ず反映させます</li></ul><hr><h1 id="ストーリーポイント会議の進行ガイド" tabindex="-1">ストーリーポイント会議の進行ガイド <a class="header-anchor" href="#ストーリーポイント会議の進行ガイド" aria-label="Permalink to “ストーリーポイント会議の進行ガイド”">​</a></h1><h2 id="会議アジェンダ" tabindex="-1">会議アジェンダ <a class="header-anchor" href="#会議アジェンダ" aria-label="Permalink to “会議アジェンダ”">​</a></h2><h3 id="オープニング-5分" tabindex="-1">オープニング (5分) <a class="header-anchor" href="#オープニング-5分" aria-label="Permalink to “オープニング (5分)”">​</a></h3><ul><li>会議の目的説明：今回のスプリントの作業難易度/複雑さを相対的に見積もる</li><li>絶対的な時間単位ではなく、相対的な規模の比較を通じて合意することの強調</li></ul><h3 id="基本概念のリマインド-10分" tabindex="-1">基本概念のリマインド (10分) <a class="header-anchor" href="#基本概念のリマインド-10分" aria-label="Permalink to “基本概念のリマインド (10分)”">​</a></h3><ul><li>ストーリーポイントの定義：作業の規模、複雑さ、不確実性を表す単位</li><li>時間と1:1でマッピングしない (❌ 「5ポイント = 1ポイントの5倍の時間」)</li><li>フィボナッチ数列を使用する理由の説明 (1, 2, 3, 5, 8, 13, 21...)</li></ul><h3 id="基準事例の共有-10分" tabindex="-1">基準事例の共有 (10分) <a class="header-anchor" href="#基準事例の共有-10分" aria-label="Permalink to “基準事例の共有 (10分)”">​</a></h3><ul><li>ストーリーポイントの例の共有 (ユーザー調査 → 3、ワイヤーフレーム → 5 など)</li><li>具体的な基準課題の検討 (5ポイント：パスワードリセット、13ポイント：クレジットカード決済)</li></ul><h3 id="間違った使い方の注意-5分" tabindex="-1">間違った使い方の注意 (5分) <a class="header-anchor" href="#間違った使い方の注意-5分" aria-label="Permalink to “間違った使い方の注意 (5分)”">​</a></h3><ul><li>時間をそのまま代入しないことを強調</li><li>「5ポイント = 1ポイントの5倍の時間」 ❌</li><li>正しい解釈：「1ポイントよりも5倍複雑だ」</li></ul><h3 id="リファクタリングおよび品質の考慮-10分" tabindex="-1">リファクタリングおよび品質の考慮 (10分) <a class="header-anchor" href="#リファクタリングおよび品質の考慮-10分" aria-label="Permalink to “リファクタリングおよび品質の考慮 (10分)”">​</a></h3><ul><li>すべてのストーリーには [1] 正しく動作 + [2] 適切に動作(品質) を含める必要がある</li><li>リファクタリング/技術的負債の改善も状況に応じてポイント策定が必要</li><li>個人の成果比較用ではないことを再強調</li></ul><h3 id="実際の作業の見積もり-30〜40分" tabindex="-1">実際の作業の見積もり (30〜40分) <a class="header-anchor" href="#実際の作業の見積もり-30〜40分" aria-label="Permalink to “実際の作業の見積もり (30〜40分)”">​</a></h3><ul><li>バックログアイテムを1つずつ確認</li><li>基準事例と比較して議論</li><li>チーム合意 → フィボナッチ数の中から1つを決定 (例：3, 5, 8, 13)</li><li>問題や意見の対立がある場合は妥協点を見つける</li></ul><h3 id="まとめ-5分" tabindex="-1">まとめ (5分) <a class="header-anchor" href="#まとめ-5分" aria-label="Permalink to “まとめ (5分)”">​</a></h3><ul><li>会議で決めたストーリーポイントの結果の整理</li><li>次のスプリント計画時に反映する予定であることを知らせる</li><li>「ストーリーポイントは、チームのスケジュールを素早く簡単に見積もるためのツール」であることを再強調</li></ul><p>ストーリーポイントはチームの生産性とスケジュール管理に有用なツールですが、正しく理解して使用した時にその真の価値を発揮します。</p><hr>`,50)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};